SELECT TS.SERVICE_ID, TS.WORK_CD, TS.CAR_NO, TS.COMPANY_ID, TC.COMPANY_NM, TS.MEMBER_ID, TO_CHAR(TS.REQUEST_DT, 'MM.DD HH24:MI') AS REQUEST_DT, TO_CHAR(TS.PROC_DT, 'YYYYMMDD') AS PROC_DT, TS.PROC_ST, TS.GOVT_ID, TMD.MEMBER_NM, TS.JUDGE_ST, TO_CHAR(TS.JUDGE_DT, 'YYYYMMDD') AS JUDGE_DT FROM TR_SERVICE TS, TM_COMPANY TC, TM_MEMBER_DT TMD WHERE TS.COMPANY_ID = TC.COMPANY_ID AND TS.MEMBER_ID = TMD.MEMBER_ID AND TS.REQUEST_DT BETWEEN TO_DATE(#{START_DT} || '00:00:00', 'YYYYMMDDHH24:MI:SS') AND TO_DATE(#{END_DT} || '23:59:59', 'YYYYMMDDHH24:MI:SS') AND TS.WORK_CD LIKE 'MORT%'
AND TS.WORK_CD = #{WORK_CD}
AND TS.COMPANY_ID = #{COMPANY_ID}
AND TS.PROC_ST = #{PROC_ST}
AND TS.CAR_NO LIKE '%' || #{CAR_NO} || '%'
AND TS.GOVT_ID = #{GOVT_ID}
ORDER BY TS.REQUEST_DT DESC

SELECT ASSOCIATION_ID, COMPANY_ID, BIZ_NO, COMPANY_NO, COMPANY_NM, CEO_NM, POST_NO, ADDRESS, ADDRESS_DT, TEL_NO, MPHONE_NO, RT_BANK_CD, RT_ACC_NO, RT_ACC_NM, USE_YN FROM TM_COMPANY WHERE USE_YN = 'Y'
AND ASSOCIATION_ID = #{ASSOCIATION_ID}
AND COMPANY_ID = #{COMPANY_ID}
